const repositoryStars={"anthropics/skills": 194336, "coreyhaines31/marketingskills": 60235, "designed-by-ai/skills": 35, "emilkowalski/skills": 56782, "flowkit-labs/skills": 38, "gencraft-labs/skills": 3, "github/awesome-copilot": 41148, "google/agents-cli": 6348, "heygen-com/hyperframes": 84130, "juliusbrussee/caveman": 119776, "larksuite/cli": 18103, "leonxlnx/taste-skill": 115295, "lllllllama/rigorpilot-skills": 486, "mattpocock/skills": 324124, "microsoft/azure-skills": 1639, "nextlevelbuilder/ui-ux-pro-max-skill": 149274, "obra/superpowers": 317409, "prime-skills/runcomfy-agent-skills": 62, "remotion-dev/skills": 6997, "supabase/agent-skills": 3056, "vercel-labs/agent-browser": 50923, "vercel-labs/agent-skills": 34046, "vercel-labs/skills": 39320};
function skillRepository(item){if((item.url||'').includes('/site/'))return null;const command=(item.command||'').match(/(?:skills add|--repo)\s+([\w.-]+\/[\w.-]+)/i);if(command)return command[1].replace(/\.git$/,'');const url=(item.url||'').match(/github\.com\/([\w.-]+\/[\w.-]+)/i);if(url)return url[1].replace(/\.git$/,'');const marketplace=(item.url||'').match(/skills\.sh\/([\w.-]+\/[\w.-]+)/i);return marketplace?marketplace[1]:null}
function skillStarText(item){const repo=skillRepository(item),count=repo&&repositoryStars[repo];return count!=null?`★ ${count.toLocaleString()} 仓库 Star`:!repo?'外部资源 · 不适用 GitHub Star':'仓库 Star 待核验'}
